\label{ClosedSubspaceProp}
Let $X$ be a separable Banach space.  Then every closed subset (e.g.\ closed subspace) of $X$
is separable.  In particular, every $\mathrm{C}^*$-subalgebra of a separable $\mathrm{C}^*$-algebra is separable.

\label{PropII313}
	Let $A$ be a $\mathrm{C}^*$-algebra.  Then
	\begin{enumerate}
		\item[(i)]  $A_+$ is a closed cone in $A$; in particular, if $x,y\in A_+$, then $x+y\in A_+$.
		\item[(ii)]  If $x\in A$, then $x^*x\geq0$.
	\end{enumerate}

\label{UniquePosSqrtProp}
	Let $A$ be a $\mathrm{C}^*$-algebra, $0\leq x\in A$.  Then there is a unique positive 
	$a\in A$ with $a^2=x$.

\label{RepCAlg}
	A $\mathrm{C}^*$-algebra $A$ is {\em representable} if it is isomorphic to a closed *-algebra of bounded operators
	on a Hilbert space.

\label{RepThm}
	Let $A$ be a separable (unital) $\mathrm{C}^*$-algebra, and $x\in A$.  Then there is a state $\psi$ on $A$ with
	$\psi(x^*x)=\|x\|^2$.  In particular, the states on $A$ determine the norm, so $A$ is representable.

\label{SepRepThm}
Every separable $\mathrm{C}^*$-algebra has a faithful representation as a concrete $\mathrm{C}^*$-algebra of operators
on a separable Hilbert space.

\label{P.Russell.example} Suppose that there exists a Russell set $X$. Then the following holds. 
	\begin{enumerate}
		\item \label{1.Russell.example} Some unital commutative $\mathrm{C}^*$-algebra $A$  is concretely representable on a Hilbert space but it is not isomorphic to $C(Z)$ for any compact Hausdorff space~$Z$. This algebra is an inductive limit of a sequence of finite-dimensional $\mathrm{C}^*$-algebras (but it is not separable).  
		\item \label{2.Russell.example} The state space of $A$ is not compact, and has no extreme points. 
		\end{enumerate}

\label{BHNormSepThm}
		Let ${\mathcal H}$ be a Hilbert space.  Then ${\mathcal B}({\mathcal H})$ is norm-separable if and only if ${\mathcal H}$ is 
		finite-dimensional.

\label{OrthProjSeqProp}
		Let ${\mathcal H}$ be a Hilbert space.  If ${\mathcal B}({\mathcal H})$ contains a sequence of mutually orthogonal
		nonzero projections, then ${\mathcal B}({\mathcal H})$ is not norm-separable.

\label{T.Isomorphic}
	Two standard Borel spaces are Borel-isomorphic if and only if they have the same cardinality, which is either countable or $2^{\aleph_0}$. 
	Any Borel-isomorphism between standard Borel spaces sends $\boldsymbol\Sigma^1_n$ sets to $\boldsymbol\Sigma^1_n$ sets and $\boldsymbol\Pi^1_n$ sets to $\boldsymbol\Pi^1_n$ sets  for every~$n$.

\label{T.Analytic}
	Every $\boldsymbol\Sigma^1_1$ set is absolute for transitive models of {ZF}{} that contain the parameter from which the set is defined. 
	Every $\boldsymbol\Sigma^1_1$ statement is absolute for transitive models of {ZF}{} that contain the parameter from which the set is defined.

\label{L.Axiomatizable} 
			\begin{enumerate}
				\item For each of the following properties of $\mathrm{C}^*$-algebras, the set of codes of separable $\mathrm{C}^*$-algebras that satisfy it is Borel: 
				Being finite, stably finite, purely infinite and simple. 
				\item \label{2.Axiom} The set of codes for separable $\mathrm{C}^*$-algebras that have a tracial state is $\boldsymbol\Sigma^1_1$. 

				\item \label{3.Axiom} The set of codes for separable 
				nuclear $\mathrm{C}^*$-algebras is $\boldsymbol\Pi^1_1$. 

				\item \label{4.Axiom} The set of codes for separable $\mathrm{C}^*$-algebras with CPAP is Borel. 
			\end{enumerate}

For finite, stably finite, and purely infinite and simple one only needs to observe that the defining property of the class is already first order; see the proof  of  \cite[Theorem~2.5.1]{Muenster}. 

\eqref{2.Axiom}
Let $A$ be a code for a separable $\mathrm{C}^*$-algebra. 
Since the space $\mathsf S(A)$ of states of $A$ is a compact metrizable space (Lemma~\ref{L.S(A)}) and the evaluation function is continuous, the space of all tracial states of $A$ is closed and the assertion that it is nonempty is $\boldsymbol\Sigma^1_1$. 

\eqref{4.Axiom}
The class $\mathrm{C}^*$-algebras with CPAP is Borel by a result of Effros (\cite[Theorem~1.2]{Kec:C*}).  This result is stated using the equivalence of nuclearity and CPAP, but from the proof it is clear that CPAP is used. An alternative proof of this, and Borelness of related approximation properties (such as for example small nuclear dimension) can also be extracted from \cite[Theorem~5.7.3]{Muenster}.  

		\eqref{3.Axiom}		
For nuclearity, 	fix a (code for) a separable $\mathrm{C}^*$-algebra $A$. 
Then $A$ is not nuclear if and only if there is a $\mathrm{C}^*$-algebra $B$ with $\|\cdot\|_{\max}\neq\|\cdot\|_{\min}$ on $A\odot B$.  For such a $B$, there is a $z=\sum_{k=1}^n x_k\otimes y_k\in A\odot B$ with $\|z\|_{\max}>\|z\|_{\min}$.  Then $\|\cdot\|_{\max}\neq\|\cdot\|_{\min}$ on $A\odot C^*(y_1,\dots,y_n)$.
Therefore, we may assume $B$ is separable.  Since both $A$ and $B$ are separable, $\|\cdot\|_{\min}$ is the norm in a GNS-representation by states of the form $\psi\otimes \eta$, where $\psi$ and $\eta$ are faithful states of $A$ and $B$.  

\paragraph{}\begin{Claim} 
The set of all triples $(B,x,\varphi,\psi,\eta)$ where $B$ is a code for a separable $\mathrm{C}^*$-algebra, $x$ is a sum of $n$ elementary tensors in $A\odot B$ for some $n\in \mathbb{N}$, $\varphi$ is a state on $A\odot B$, $\psi$ and $\eta$ are faithful states on $A$ and $B$ and  
\[
\|\pi_\varphi(x)\|>\|x\|_{\psi\otimes \eta} 
\]
is Borel. 
\end{Claim}
\begin{Proof}
	First, states, faithful states, and finite sums of elementary tensors all have standard Borel codings. Second, each of the two GNS norms is a Borel function of the codes for states. 
\end{Proof}

Finally, since $\pi_\psi$ and $\pi_\eta$ are faithful, the right-hand side in the displayed formula of the Claim is equal to $\|x\|_{\min}$. 
	Therefore, the set of codes for non-nuclear $\mathrm{C}^*$-algebras is, as the projection of this set,~$\boldsymbol\Sigma^1_1$. 
	This implies that the set of codes for nuclear $\mathrm{C}^*$-algebras is $\boldsymbol\Pi^1_1$ as claimed.

\label{T.absoluteness.C*.separable} Each one of the following statements is absolute between transitive models of {ZF}{} that contain all countable ordinals. 
\begin{enumerate}
	\item \label{1.Abs} Every separable, stably finite, $\mathrm{C}^*$-algebra has a tracial state. 
	\item \label{nuclear-UCT} Every separable, nuclear $\mathrm{C}^*$-algebra satisfies the Universal Coefficient Theorem (UCT). 
	\item \label{CPAP-UCT} Every separable $\mathrm{C}^*$-algebra with CPAP satisfies the Universal Coefficient Theorem (UCT). 
\end{enumerate}

\eqref{1.Abs}
By Lemma~\ref{L.Axiomatizable}, the set of codes in $\hat\Xi$  corresponding to separable $\mathrm{C}^*$-algebras that are stably finite and have no tracial state is $\boldsymbol\Pi^1_1$. Thus the assertion that this set is empty is $\boldsymbol\Pi^1_2$, hence absolute between transitive models of {ZF}{} that contain all countable ordinals by Theorem~\ref{T.Shoenfield}. 

\eqref{nuclear-UCT} and \eqref{CPAP-UCT}
The set of codes for separable $\mathrm{C}^*$-algebras with UCT is $\boldsymbol\Sigma^1_1$ by \cite[Theorem~3.27]{pi2026game}. By Lemma~\ref{L.Axiomatizable}, \eqref{CPAP-UCT}  asks whether a concrete Borel set is included in a concrete $\boldsymbol\Sigma^1_1$ set and \eqref{nuclear-UCT} asks whether a concrete~$\boldsymbol\Pi^1_1$ set is included in a concrete $\boldsymbol\Sigma^1_1$ set. Thus each of these two statements is equivalent to asserting that every code for a separable $\mathrm{C}^*$-algebra belongs to a certain~$\boldsymbol\Sigma^1_1$ set. Such statement is equivalent to a $\boldsymbol\Pi^1_2$ statement, and therefore absolute for transitive models of {ZF}{} that contain all countable ordinals by Shoenfield's Absoluteness Theorem, Theorem~\ref{T.Shoenfield}.
